"""Match payout. Rules live in docs/ECONOMY.md."""

from decimal import ROUND_HALF_UP, Decimal


def _dec(value):
    return Decimal(str(value))


def match_payout(won, kills, cfg):
    base = _dec(cfg["win_base"] if won else cfg["loss_base"])
    raw = (base + _dec(kills) * _dec(cfg["kill_bonus"])) * _dec(cfg["event_multiplier"])
    # Round to the nearest ten, halves always rounding up (1425 -> 1430, 1585 -> 1590).
    # Decimal arithmetic avoids binary float drift (e.g. 1450 * 1.1 == 1594.9999999999998).
    return int((raw / 10).quantize(Decimal("1"), rounding=ROUND_HALF_UP) * 10)


